try:
    from PySide6 import QtWidgets
except ImportError:
    from PySide2 import QtWidgets
cur = hou.getPreference('custom.bx.enabled')
if cur == '':
    hou.addPreference('custom.bx.enabled', '0')
    new_val = '0'
else:
    new_val = '0' if cur == '1' else '1'
    hou.setPreference('custom.bx.enabled', new_val)

app = QtWidgets.QApplication.instance()
if new_val == '0':
    if hasattr(hou.session, 'bx_network_filter') and hou.session.bx_network_filter is not None:
        app.removeEventFilter(hou.session.bx_network_filter)
else:
    if hasattr(hou.session, 'bx_network_filter') and hou.session.bx_network_filter is not None:
        app.installEventFilter(hou.session.bx_network_filter)

cur = hou.getPreference('custom.bx.rotate')
if cur == '':
    hou.addPreference('custom.bx.rotate', '1')
else:
    hou.setPreference('custom.bx.rotate', '0' if cur == '1' else '1')
